import { Brain } from "../components/Brain.js";
import { Faction } from "../components/Faction.js";
import { Position } from "../components/Position.js";
import { Vitality } from "../components/Vitality.js";
import { hasLOS } from "../../shared/math/gridLOS.js";
import { hasOverworldAerialLOS } from "./flyingEligibility.js";
import { areFactionsHostile } from "./factionHostility.js";
import { forEachInRadius } from "./spatialIndex.js";
import { buildBlocksVisionMap, blockedCallback } from "./vision.js";
import { getEffectiveVisionRange } from "./blind.js";

/**
 * Shared brain-backed sight query for actor cognition.
 * Returns null if the actor has no Brain: sight-based decisions should not
 * silently fall back to omniscience.
 *
 * @param {any} world
 * @param {number} actorId
 * @param {number} targetId
 * @param {{ isBlocked?: (x:number, y:number)=>boolean }} [opts]
 * @returns {{ id:number, x:number, y:number, dist:number } | null}
 */
export function perceiveEntity(world, actorId, targetId, opts = {}) {
  const actor = Number(actorId || 0) | 0;
  const target = Number(targetId || 0) | 0;
  if (!(actor > 0) || !(target > 0) || actor === target) return null;
  if (!world.has(actor, Brain)) return null;

  const actorPos = world.get(actor, Position);
  const targetPos = world.get(target, Position);
  if (!actorPos || !targetPos) return null;

  const targetVit = world.get(target, Vitality);
  if (targetVit && (targetVit.hp | 0) <= 0) return null;

  const range = Math.max(0, Math.trunc(getEffectiveVisionRange(world, actor)));
  const dist = Math.max(Math.abs((targetPos.x | 0) - (actorPos.x | 0)), Math.abs((targetPos.y | 0) - (actorPos.y | 0)));
  if (dist > range) return null;

  const isBlocked = opts.isBlocked || blockedCallback(buildBlocksVisionMap(world));
  const canSee = hasOverworldAerialLOS(world, {
    sourceId: actor,
    targetId: target,
    sourcePos: actorPos,
    targetPos,
    range,
  }) || hasLOS(actorPos.x | 0, actorPos.y | 0, targetPos.x | 0, targetPos.y | 0, isBlocked);
  if (!canSee) return null;

  return { id: target, x: targetPos.x | 0, y: targetPos.y | 0, dist };
}

/**
 * Find the nearest visible hostile entity using the actor's Brain and faction.
 *
 * @param {any} world
 * @param {number} actorId
 * @param {{ isBlocked?: (x:number, y:number)=>boolean }} [opts]
 * @returns {{ id:number, x:number, y:number, dist:number } | null}
 */
export function nearestPerceivedHostile(world, actorId, opts = {}) {
  const actor = Number(actorId || 0) | 0;
  if (!(actor > 0) || !world.has(actor, Brain)) return null;
  const actorPos = world.get(actor, Position);
  const actorFaction = world.get(actor, Faction)?.key || "";
  if (!actorPos || !actorFaction) return null;

  const range = Math.max(0, Math.trunc(getEffectiveVisionRange(world, actor)));
  const isBlocked = opts.isBlocked || blockedCallback(buildBlocksVisionMap(world));
  let best = null;
  let bestDist = Infinity;

  forEachInRadius(world, actorPos.x, actorPos.y, range, (id) => {
    if (id === actor) return;
    const targetFaction = world.get(id, Faction)?.key || "";
    if (!targetFaction) return;
    if (!areFactionsHostile(actorFaction, targetFaction)) return;
    const seen = perceiveEntity(world, actor, id, { isBlocked });
    if (!seen || seen.dist >= bestDist) return;
    best = seen;
    bestDist = seen.dist;
  });

  return best;
}
import { SleepState } from "../components/SleepState.js";
import { statusStrength } from "./statusFacade.js";

export const SLEEP_STATUS = "sleep";
export const SLEEP_DISPLAY_TAG = "sleeping";

/**
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {number} id
 * @returns {boolean}
 */
export function isAsleep(world, id) {
  return statusStrength(world, Number(id || 0) | 0, SLEEP_STATUS) > 0;
}

export function sleepPreventsAction(world, id) {
  return isAsleep(world, id);
}

export function sleepPreventsMovement(world, id) {
  return isAsleep(world, id);
}

export function sleepPreventsPerception(world, id) {
  return isAsleep(world, id);
}

/**
 * Canonical sleep transition. Returns true only when this call changes state
 * from awake to asleep. Existing SleepState data may still be refreshed.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {number} id
 * @param {{ reason?: string, wakeDifficulty?: number, wakeRadius?: number, wakeOnDamage?: boolean, source?: number, suppressEvent?: boolean }} [opts]
 * @returns {boolean}
 */
export function putActorToSleep(world, id, opts = {}) {
  const actorId = Number(id || 0) | 0;
  if (!(actorId > 0)) return false;
  if (typeof world?.isAlive === "function" && !world.isAlive(actorId)) return false;

  const prev = world.get(actorId, SleepState);
  const wasAsleep = prev?.asleep === true;
  const next = {
    ...(prev || {}),
    asleep: true,
    wakeDifficulty: Math.max(0, Number(opts.wakeDifficulty ?? prev?.wakeDifficulty ?? 8) || 0),
    wakeRadius: Math.max(0, Number(opts.wakeRadius ?? prev?.wakeRadius ?? 2) || 0),
    wakeOnDamage: opts.wakeOnDamage ?? prev?.wakeOnDamage ?? true,
  };

  if (world.has(actorId, SleepState)) world.set(actorId, SleepState, next);
  else world.add(actorId, SleepState, next);

  if (!wasAsleep && opts.suppressEvent !== true) {
    world.emit?.("sleep:slept", {
      actor: actorId,
      reason: String(opts.reason || "sleep"),
      source: Number(opts.source || 0) | 0,
    });
  }
  return !wasAsleep;
}

/**
 * Canonical wake transition. Returns true only when this call changes state.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {number} id
 * @param {{ reason?: string, intensity?: number, source?: number }} [opts]
 * @returns {boolean}
 */
export function tryWakeActor(world, id, opts = {}) {
  const actorId = Number(id || 0) | 0;
  if (!(actorId > 0)) return false;
  const sleep = world.get(actorId, SleepState);
  if (!sleep || sleep.asleep !== true) return false;

  const reason = String(opts.reason || "disturbance");
  const intensity = Number.isFinite(opts.intensity) ? Number(opts.intensity) : 0;
  const difficulty = Math.max(0, Number(sleep.wakeDifficulty || 0));
  if (reason !== "damage" && difficulty > 0 && intensity < difficulty) {
    return false;
  }

  world.set(actorId, SleepState, { ...sleep, asleep: false });
  world.emit?.("sleep:woke", {
    actor: actorId,
    reason,
    intensity,
    source: Number(opts.source || 0) | 0,
  });
  return true;
}
